<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_permission('PRESUPUESTO_VER');if(!user_can_view_department_financials($user))json_response(['ok'=>false,'error'=>'Tu perfil no tiene acceso a información presupuestal agregada'],403);$year=max(2020,min(2100,(int)($_GET['year']??date('Y'))));$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$ids=visible_department_ids($db,$user);if(!$ids){$db->close();json_response(['ok'=>true,'data'=>[]]);}$list=implode(',',array_map('intval',$ids));$sql="SELECT d.departamento_id,d.codigo,d.nombre,d.color_hex,COALESCE(pd.presupuesto_asignado,0) presupuesto_asignado,COALESCE(pd.observaciones,'') observaciones,COALESCE(SUM(CASE WHEN pm.tipo='ENTRADA' AND pm.estatus='REGISTRADO' THEN pm.monto ELSE 0 END),0) entradas,COALESCE(SUM(CASE WHEN pm.tipo='SALIDA' AND pm.estatus='REGISTRADO' THEN pm.monto ELSE 0 END),0) salidas FROM departamento d LEFT JOIN presupuesto_departamento pd ON pd.departamento_id=d.departamento_id AND pd.ejercicio=$year LEFT JOIN presupuesto_movimiento pm ON pm.departamento_id=d.departamento_id AND pm.ejercicio=$year WHERE d.departamento_id IN ($list) AND d.estatus='ACTIVO' GROUP BY d.departamento_id,d.codigo,d.nombre,d.color_hex,pd.presupuesto_asignado,pd.observaciones ORDER BY d.nombre";$rs=$db->query($sql);$data=[];while($r=$rs->fetch_assoc()){$a=(float)$r['presupuesto_asignado'];$e=(float)$r['entradas'];$s=(float)$r['salidas'];$data[]=['departamento_id'=>(int)$r['departamento_id'],'codigo'=>$r['codigo'],'nombre'=>$r['nombre'],'color_hex'=>$r['color_hex'],'presupuesto_asignado'=>$a,'observaciones'=>$r['observaciones'],'entradas'=>$e,'salidas'=>$s,'disponible'=>$a+$e-$s,'ejercido_pct'=>$a>0?round(($s/$a)*100,1):0];}$db->close();json_response(['ok'=>true,'data'=>$data]);
